learn=[('Run the real headless CLI', 'Use the pinned bundled claude binary with -p and JSON output. Compare ordinary project-memory discovery with --bare plus an explicit rules file. Reduced configuration discovery does not make model outputs deterministic.'), ('Parse native machine-readable results', 'Inspect the actual CLI JSON envelope, result subtype, structured_output, cost estimate, stdout, stderr and process exit. Invalid JSON Schema produces a real validator diagnostic before model work.'), ('Build an unattended SDK step', 'Use settingSources: [], explicit tools, dontAsk and finite turn/spend estimates. A known unapproved command is denied by the native permission mode rather than waiting for a human.'), ('Fix a trusted lint fixture', 'The SDK runs a tiny teaching linter, changes only var message to const message and reruns lint and tests. The host verifies the exact source change and independently runs the same trusted checks; this is not a general-purpose ESLint bot.'), ('Gate on evidence and actual exit codes', 'Native model success and CI policy are separate. The worker exits nonzero for a denied tool, incomplete run, schema failure or failed lint gate. The browser observes the actual OS process exit instead of displaying an invented pass badge.'), ('Configure GitHub workflows safely', 'Source checks run without an API key. A manual main-branch agent workflow uses a repository secret when you choose to configure it. A Claude Code Action reference is included separately; no hosted agent run, comment, PR or automatic commit is performed by the classroom app.')]
labels=[('cli', 'CLI -p JSON and project discovery'), ('context', 'Bare CLI with explicit rules'), ('structured', 'CLI JSON Schema - function names'), ('sdk', 'Unattended read-only SDK job'), ('fix', 'SDK lint fix - independent verification'), ('deny', 'dontAsk - deny an unapproved command'), ('turnlimit', 'CLI one-turn limit - actual failure'), ('schema', 'Invalid JSON Schema - fail before model'), ('gate', 'Model success, failed lint gate')]
runsteps=[('Prerequisites', 'Use Node.js 24+, Git, API credit and a supported model. Windows may need Git Bash. npm ci installs the pinned SDK and its matching native CLI; no global claude install, Docker, database or GitHub token is needed for local experiments.', 'node --version\nnpm --version\ngit --version'), ('Install and create the private .env', 'From the course presentations folder use the cd command shown; in a standalone clone start at its repository root and skip that line. Preserve an existing .env or copy the template. Enter your API key privately in the same shell that starts the app; inherited shell variables take precedence.', 'cd .\\agent-sdk\\lesson55-ci-cd\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and compare pipeline paths', 'Keep the terminal open and explore all five student pages. Select a fixed experiment, then inspect actual configuration, native JSON, commands, Git diff and real job-process exit. Each run generates a fresh trusted Git fixture rather than modifying this application or a user repository.', 'npm start\n# http://127.0.0.1:3155\n# Terminal equivalent:\nnpm run pipeline -- sdk'), ('Compare CLI discovery and structured output', 'CLI runs -p without --bare and can load the fixture CLAUDE.md marker AUTO-DISCOVERY-55. Context uses --bare plus an explicit CI55-EXPLICIT rules file. Structured returns the actual exported names greet and isReady. This controlled comparison is about configuration loading, not deterministic answers.', 'npm run pipeline -- cli\nnpm run pipeline -- context\nnpm run pipeline -- structured'), ('Inspect intentional failures', 'Fix should finish with exact var-to-const diff and independent lint/test exit 0. Deny, Turnlimit, Schema and Gate intentionally produce actual job exit 1. Gate demonstrates native success while the unmodified fixture still fails lint. A failed command is an expected lesson outcome, not a reason to pretend the pipeline passed.', 'npm run pipeline -- fix\nnpm run pipeline -- deny\nnpm run pipeline -- turnlimit\nnpm run pipeline -- schema\nnpm run pipeline -- gate\n# PowerShell: inspect the preceding command exit\n$LASTEXITCODE'), ('Enable hosted agent jobs only when ready', 'The source-check workflow runs npm test without API secrets. For hosted agent jobs, open the repository Settings > Secrets and variables > Actions > New repository secret and privately add ANTHROPIC_API_KEY. Then choose Actions > Manual trusted-fixture agent job > Run workflow on main. This application does not upload that secret. The Claude Code Action reference remains under .github/examples; review the official app setup before copying it into workflows. No recurring cron or mention-triggered automation is enabled.', 'npm test\n# Local evidence: .runtime/runs/<run-id>/evidence.json\n# Hosted workflow: .github/workflows/agent-demo.yml\n# Optional reference: .github/examples/claude-code-action.yml')]
specs=[('Validate the chosen classroom job', 'src/protocol.ts', 'if (', 'The browser chooses only a fixed experiment. It cannot submit arbitrary shell commands, prompts, workflow expressions or filesystem paths.', 0, 1, 7), ('Prepare a real trusted Git checkout', 'src/workspace.ts', 'await git("init"', 'Generate a fresh fixture, initialize actual Git history and commit its trusted baseline locally. It is not a clone of an untrusted PR and never changes the application repository.', 1, 3, 7), ('Spawn the actual pipeline worker', 'src/agent.ts', 'const child = spawn(', 'Launch a real Node/tsx job process with argument arrays and shell:false. The host observes stdout, stderr and the actual exit event; no shell command is composed from browser input.', 1, 2, 10), ('Build headless CLI JSON arguments', 'src/job.ts', 'const args = [', 'The worker resolves the SDK-pinned native claude executable and supplies -p, optional --bare and JSON output. Tool, turn and estimate limits are explicit; the UI preserves its actual native process result.', 2, 2, 10), ('Pass context explicitly in bare mode', 'src/job.ts', 'if (mode === "context")', 'Bare skips automatic project-memory discovery. The explicit append-system-prompt-file option supplies the reviewed classroom rule, so the result includes CI55-EXPLICIT without relying on ambient CLAUDE.md.', 1, 2, 6), ('Request and validate a real JSON schema', 'src/job.ts', 'if (mode === "structured" || mode === "schema")', 'Pass the schema as a literal process argument, not shell-generated text. Structured parses the actual functions field. Schema mode deliberately supplies an invalid type and preserves the native validator failure.', 1, 2, 8), ('Capture native stdout, stderr and exit', 'src/processes.ts', 'child.once("close"', 'Capture the real child-process exit and its separate output streams. A native JSON result, validator diagnostic and process failure are different evidence, not interchangeable strings.', 2, 1, 8), ('Configure an unattended SDK job', 'src/job.ts', 'allowedTools: [', 'settingSources is empty, tools are declared, turns and estimated spend are finite, and dontAsk denies unresolved calls. It is not bypassPermissions. Callback hooks still enforce the trusted fixture scope.', 1, 2, 9), ('Permit only exact fixture commands', 'src/policy.ts', 'if (name === "Bash")', 'Fix mode permits only the exact linter and test commands. The harmless forbidden-command test is deliberately deferred to native dontAsk, which must deny it. Every other command is refused by the host.', 1, 2, 8), ('Consume the actual SDK stream', 'src/job.ts', 'const run = query({ prompt, options });', 'The real SDK owns model/tool orchestration. Preserve native messages, tool requests and the final result instead of creating a manual model loop or simulated responses.', 2, 3, 9), ('Independently verify the model fix', 'src/job.ts', 'if ((mode === "fix" || mode === "gate") && fixturesValid)', 'Only after exact fixture validation may the host execute its known linter and tests. The API key is removed from these verification processes. A model claim that lint passed is not accepted as verification.', 1, 3, 10), ('Map native and policy checks to a gate', 'src/policy.ts', 'return input.nativeSuccess', 'Require native success, valid fixture state, no denials and successful required checks. Thus an SDK success can still produce a failed CI gate when real lint fails.', 1, 4, 10), ('Exit with the real pipeline decision', 'src/job.ts', 'process.exitCode = evidence.pipelineExitCode;', 'Set the job process exit after retaining evidence and cleaning temporary state. The parent observes that actual OS exit and compares it with the reported decision before updating the browser.', 4, 0, 2)]
reference=[('Real local jobs versus hosted automation', 'The app runs actual native CLI and SDK processes locally on generated trusted fixtures. It does not post comments, open PRs, auto-commit fixes or run a hosted GitHub agent job. The public repository includes offline source checks and a manual secret-dependent workflow for you to enable.'), ('Bare mode is not deterministic inference', '--bare skips discovery of hooks, skills, commands, subagents, plugins, MCP, auto memory and CLAUDE.md. Explicit options can still supply context. It reduces ambient configuration differences; it does not guarantee identical text, eliminate managed policy or create an OS sandbox.'), ('A controlled discovery comparison', 'The ordinary CLI case sees the benign fixture CLAUDE.md marker AUTO-DISCOVERY-55. Context adds --bare and a reviewed rules file containing CI55-EXPLICIT. The trusted fixture README separately identifies the project as CI55-DEMO. No real user configuration or untrusted PR instruction is deliberately imported.'), ('CLI JSON and invalid schema', 'CLI stdout is the actual JSON result in ordinary cases. Schema uses a real invalid JSON Schema type and preserves the actual stderr validator diagnostic and nonzero native process exit. It does not invent a model outage or synthesize a result object when stdout is not JSON.'), ('dontAsk is an unattended gate', 'Unapproved calls are denied rather than waiting for a user. Deny submits only the harmless known fixture command once, allowing the native permission mode to reject it; the marker file must remain absent. Other unreviewed commands are blocked by the host before execution.'), ('A deliberately small lint task', 'The generated fixture uses a tiny regex teaching linter, not ESLint. The only permitted edit is var message to const message in src/greeting.js. Hooks reject arbitrary edits and shell combinations. The parent verifies exact file contents before running independent trusted checks.'), ('Native success differs from job success', 'Gate leaves the lint issue intact, lets the native read-only SDK task succeed, then fails the real lint check. The worker must exit 1. Fix must have the expected diff plus independent lint/test exit 0 before its actual process may pass. The UI displays actual and reported process exits separately.'), ('Secrets and trusted runners', 'The key lives only in private .env or a shell. Non-model verification subprocesses do not receive it. Never give credentials to untrusted PR code, repository hooks, package scripts or arbitrary agent-generated programs. Tool policies are not OS isolation; production runners need appropriate sandboxing, identity and repository trust controls.'), ('Bound work and costs', 'CLI tasks allow six turns, or one for the limit case, with a $0.30 estimate threshold. SDK read tasks allow six turns and fix allows ten, with a $0.35 threshold. Worker timeout is five minutes. Estimates can overshoot before checks and are not hard prepaid caps.'), ('Workflow triggers and permissions', 'ci.yml checks source on push/main and pull requests without API secrets. agent-demo.yml is manual, main-only and contents-read; the selected input is an enum passed through an environment variable, not interpolated as shell code. Checkout does not persist credentials. No recurring schedule is enabled.'), ('Claude Code Action alternative', 'The optional reference uses anthropics/claude-code-action and repository secrets, with explicit CLI arguments. It remains outside .github/workflows until you review official GitHub App setup and choose to enable it. Mention-based issue/PR actions and scheduled prompts are explained, not activated by this app.'), ('Evidence and platform support', 'Native stdout/stderr, JSON, tool observations, independent checks and real Git diff are retained in the ignored runtime folder. Windows may need Git Bash. The pinned SDK supplies a matching platform CLI; no global claude binary or jq installation is required for the app.'), ('Primary references', 'https://code.claude.com/docs/en/headless ; https://code.claude.com/docs/en/cli-reference ; https://github.com/anthropics/claude-code-action ; https://docs.github.com/en/actions/reference/security/secure-use')]
body='<div class="flow"><div><b>01 · Configure</b><p>Select a real pipeline experiment</p></div><span>→</span><div><b>02 · Observe</b><p>Run the real SDK</p></div><span>→</span><div><b>03 · Verify</b><p>Inspect JSON, diff and actual exits</p></div></div><section class="panel" id="controls"><h2>Run agents without waiting for a human</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Pipeline experiment</label><select id="mode"><option value="cli">CLI -p JSON and project discovery</option><option value="context">Bare CLI with explicit rules</option><option value="structured">CLI JSON Schema - function names</option><option value="sdk">Unattended read-only SDK job</option><option value="fix">SDK lint fix - independent verification</option><option value="deny">dontAsk - deny an unapproved command</option><option value="turnlimit">CLI one-turn limit - actual failure</option><option value="schema">Invalid JSON Schema - fail before model</option><option value="gate">Model success, failed lint gate</option></select><button class="primary" id="run" disabled>Run pipeline job →</button><p>Real headless CLI and SDK jobs run on a fresh trusted Git fixture. Observe actual process exits, native JSON, scoped lint changes and independent checks. Some cases intentionally exit 1. No hosted agent run, comment, PR or automatic commit is performed.</p></section><section class="step" id="specialists-panel"><h2>Actual pipeline evidence</h2><div class="grid"><article class="card"><h3>Actual job exit</h3><p class="metric" id="span-count">0</p></article><article class="card"><h3>Native results</h3><p class="metric" id="metric-count">0</p></article><article class="card"><h3>Native SDK tool calls</h3><p class="metric" id="log-count">0</p></article></div><p>The job exit comes from the OS process close event. CLI JSON does not expose the same tool-event stream as SDK mode; no missing CLI events are invented.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Actual CLI or SDK configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre></section></div><section class="step" id="trace-panel"><h2>SDK tool policy</h2><p>SDK hooks scope the fixture. Defer in the known denial test lets native dontAsk evaluate the unapproved command; no interactive approval is requested.</p><div class="table"><table><thead><tr><th>Tool</th><th>Host decision</th><th>Actual input</th></tr></thead><tbody id="trace-history"></tbody></table></div></section><section class="step" id="metric-panel"><h2>Actual command results</h2><p>SDK Bash results and independent host checks are labelled separately. Both are actual processes; a denied command has no successful execution row.</p><div class="table"><table><thead><tr><th>Source</th><th>Command</th><th>Actual response</th></tr></thead><tbody id="metric-history"></tbody></table></div></section><section class="step" id="model-panel"><h2>Observed pipeline stages</h2><label for="user-filter">Filter by exact observation kind</label><input id="user-filter" placeholder="configuration"><p>Leave blank for all observations, or use configuration, cli-process, tool-policy, native-tool or host-verification.</p><div class="table"><table><thead><tr><th>Stage</th><th>Actual detail</th></tr></thead><tbody id="log-history"></tbody></table></div></section><section class="step" id="results-panel"><h2>Native SDK result</h2><pre class="json-view"><code class="language-json" id="native-result">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Native SDK tool requests</h2><pre class="json-view"><code class="language-json" id="requests">{}</code></pre></section><section class="step" id="storage-panel"><h2>Fixture invariants, markers and scope</h2><pre class="json-view"><code class="language-json" id="storage">{}</code></pre></section><section class="step" id="diagnostic-panel"><h2>Native stderr, validator and execution failures</h2><pre class="json-view"><code class="language-json" id="diagnostics">{}</code></pre></section><section class="step" id="observation-panel"><h2>Actual process observations - sanitized</h2><pre class="json-view"><code class="language-json" id="telemetry">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent actual run evidence</h2><pre class="json-view"><code class="language-json" id="evidence">{}</code></pre><button id="download">Download actual observations</button></section>'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3155\n# Windows only, if required:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'

body=body.replace('<section class="step" id="specialists-panel">','<section class="step" id="process-panel"><h2>Actual process exits and CI decision</h2><pre class="json-view"><code id="process" class="language-json">{}</code></pre></section><section class="step" id="artifact-panel"><h2>Actual Git diff and independent checks</h2><pre><code id="diff" class="language-diff">Waiting for the actual job.</code></pre><pre class="json-view"><code id="host-checks" class="language-json">{}</code></pre></section>'+'<section class="step" id="specialists-panel">')
document('/','Run headless. <em>Gate on evidence.</em>','Compare real CLI and SDK pipeline jobs, actual JSON and scoped fixes with real exit codes.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Build unattended jobs, validate their work and configure trusted workflows.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your private .env</h2>'+snippet(env,'dotenv')+'<p>Keep the key private, restart after edits, and preserve an existing file. Existing shell values take precedence. If the port is occupied, change PORT.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install, configure privately and inspect the nine experiments.',body)
steps=[];arrows=[];lanes=['Student UI','Node runner','CLI / SDK','Git fixture','CI gate']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='yaml' if source.endswith('.yml') else 'javascript' if source.endswith('.js') else 'typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 55 · Configure → run → verify → gate</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{max(40,min(min(x1,x2)+10,1700-len(label)*13))}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'],s['language'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The browser starts a real local job process. It prepares a trusted Git fixture, then runs the actual headless CLI or Agent SDK. Native results, scoped changes and independent checks determine a real process exit. The gate is code within the local job, not a separately deployed CI service. Numbered steps group alternative CLI and SDK paths.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked headless pipeline workflow steps"></div>'+walk)

document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has matching coloured TypeScript.',cards(reference)+walk)

readme='# Claude Agent SDK · Lesson 55 · Build agents in CI/CD\n\nFive student pages, a real CLI and SDK pipeline lab and thirteen source-linked UML code steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson55-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson55-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations: `cd .\\agent-sdk\\lesson55-ci-cd`. Open http://127.0.0.1:3155. Node 24+, API credit and Windows Git Bash if needed.\n\n## Create your .env file\n\nCopy the template once and enter your own model key privately. Restart after edits. Existing shell values take precedence.\n\n```dotenv\n'+env+'```\n\nNo Docker, database, global CLI or GitHub token is needed locally. Hosted agent jobs require a repository secret that you configure separately.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for s in steps:readme+=f'### {s["number"]}. {s["title"]}\n\n{s["explanation"]}\n\nSource: `{s["source"]}`, selected lines {s["firstLine"]}–{s["lastLine"]}. Surrounding code omitted.\n\n```{s["language"]}\n{s["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## Validation\n\nRun `npm test` and `npm run build:client`. Regenerate pages with `python scripts/build-pages.py`. Secrets, dependencies, recordings and teaching media are excluded from Git.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
(PUBLIC/'style.css').write_text((PUBLIC/'style.css').read_text(encoding='utf-8')+'\n.metric{font-size:34px;font-weight:800}.json-view{max-height:380px}.table{max-height:420px;overflow:auto}td{min-width:140px;max-width:500px;overflow-wrap:anywhere}.markdown-body{font-size:22px;line-height:1.65}#conversation{max-height:450px;overflow:auto}input{width:100%;font:inherit;padding:16px;border:1px solid var(--line);border-radius:14px;color:var(--ink);background:var(--paper)}\n',encoding='utf-8')
print('Built five Lesson 55 pages with 13 coloured workflow snippets.')
